def write_py(filepath, questions):
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write("QUESTIONS = [\n")
        for idx, q in enumerate(questions):
            comma = ',' if idx < len(questions) - 1 else ''
            f.write('  {\n')
            f.write(f'    "stem": {json.dumps(q["stem"], ensure_ascii=False)},\n')
            opts = q["options"]
            f.write(f'    "options": {{"A": {json.dumps(opts["A"], ensure_ascii=False)}, "B": {json.dumps(opts["B"], ensure_ascii=False)}, "C": {json.dumps(opts["C"], ensure_ascii=False)}, "D": {json.dumps(opts["D"], ensure_ascii=False)}}},\n')
            f.write(f'    "answer": {json.dumps(q["answer"], ensure_ascii=False)},\n')
            f.write(f'    "analysis": {json.dumps(q["analysis"], ensure_ascii=False)},\n')
            k = q["knowledge"]
            f.write(f'    "knowledge": [{json.dumps(k[0], ensure_ascii=False)}, {json.dumps(k[1], ensure_ascii=False)}, {json.dumps(k[2], ensure_ascii=False)}],\n')
            f.write(f'    "module": {json.dumps(q["module"], ensure_ascii=False)},\n')
            f.write(f'    "difficulty": {json.dumps(q["difficulty"], ensure_ascii=False)},\n')
            f.write(f'    "target": {json.dumps(q["target"], ensure_ascii=False)},\n')
            f.write(f'    "concept": {json.dumps(q["concept"], ensure_ascii=False)}\n')
            f.write(f'  }}{comma}\n')
        f.write("]\n")

write_py('/workspace/data/comp_batch_d_m3_animal.py', Q)
